script:
"=== installing Node.js ==="
try {
  winget install --id OpenJS.NodeJS.LTS -e --accept-source-agreements --accept-package-agreements 2>&1 | Select-Object -Last 3
  "winget done"
} catch {
  "WINGET FAILED: " + $_.Exception.Message
}
"=== refreshing PATH ==="
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
"=== verifying node ==="
try { node --version } catch { "node still not found" }
try { npm --version } catch { "npm still not found" }
